local sm=require("core.scene_manager"); local input=require("core.input"); local bridge=require("core.bridge"); local font=require("core.font"); local icon=require("core.icon"); local bg=require("effects.uplink_bg")
local M={}; local CYAN={.22,.80,.98}; local st={wifi={},info={},networks={},selected=1,t=0,status="READING WI-FI STATE",busy=false}
local function C(c,a) love.graphics.setColor(c[1],c[2],c[3],a or 1) end
local function T(s,x,y,w,z,c,align,b) local f=(b and font.bold or font.regular)(z) or love.graphics.newFont(z); love.graphics.setFont(f); C(c or {.9,.94,.98}); love.graphics.printf(tostring(s or ""),x,y,w,align or "left") end
local function refresh() bridge.call("network_status",{},function(r) if r.ok and r.network then st.wifi=r.network.wifi or {}; st.info=r.network.info or {}; st.status="WI-FI STATUS UPDATED" else st.status="STATUS · "..tostring(r.error or "unavailable") end end) end
local function scan() if st.busy then return end; st.busy=true; st.status="SCANNING AVAILABLE NETWORKS…"; bridge.call("wifi_scan",{},function(r) st.busy=false; if r.ok then st.networks=r.networks or {}; st.selected=1; st.status=tostring(#st.networks).." NETWORKS FOUND" else st.status="SCAN · "..tostring(r.error or "unavailable") end end) end
local function toggle() if st.wifi.radio_on==nil then st.status="RADIO CONTROL NOT AVAILABLE"; return end; local a=st.wifi.radio_on and "radio_off" or "radio_on"; st.status="CHANGING WI-FI RADIO…"; bridge.call("wifi_action",{action=a},function(r) st.status=r.ok and ("RADIO "..string.upper(r.state or "UPDATED")) or ("RADIO · "..tostring(r.error or r.reason or "failed")); refresh() end) end
function M.enter() st.selected=1; st.busy=false; st.t=0; st.networks={}; refresh(); scan(); input.clear(); input.on("press",function(a) if a=="up" then st.selected=math.max(1,st.selected-1) elseif a=="down" then st.selected=math.min(math.max(1,#st.networks),st.selected+1) elseif a=="a" then scan() elseif a=="x" then toggle() elseif a=="y" then refresh() elseif a=="b" then sm.back() end end) end
function M.leave() input.clear() end; function M.update(dt) st.t=st.t+dt end
function M.draw()
 local W,H=love.graphics.getDimensions(); bg.draw(W,H,st.t,"wifi",CYAN,1); T("UPLINK  /  RADIO CONTROL",14,9,W-28,8,{.38,.83,.97},"left",true); T("WI-FI",14,24,W-28,21,{.94,.97,1},"left",true)
 C({.02,.055,.08},.94); love.graphics.rectangle("fill",12,59,W-24,84,7,7); C(CYAN,.55); love.graphics.rectangle("line",12,59,W-24,84,7,7); local on=st.wifi.radio_on==true; icon.draw("wifi",23,77,30,on and CYAN or {.5,.59,.67})
 T(on and "RADIO ENABLED" or st.wifi.radio_on==false and "RADIO DISABLED" or "RADIO STATE UNKNOWN",64,69,W-86,11,on and CYAN or {.7,.76,.82},"left",true); T("CONNECTED TO  "..tostring(st.wifi.ssid or "—"),64,88,W-86,8,{.82,.9,.96}); T("SIGNAL  "..tostring(st.wifi.signal or 0).."%     IP  "..tostring(st.wifi.ip or "—"),64,105,W-86,8,{.58,.72,.82}); T("GATEWAY  "..tostring(st.info.gateway or "—"),64,121,W-86,8,{.58,.72,.82})
 C({.018,.042,.064},.94); love.graphics.rectangle("fill",12,151,W-24,H-211,7,7); C(CYAN,.3); love.graphics.rectangle("line",12,151,W-24,H-211,7,7); T("VISIBLE NETWORKS",22,160,W-44,8,{.45,.82,.96},"left",true)
 for i=1,math.min(5,#st.networks) do local n=st.networks[i]; local y=181+(i-1)*34; if i==st.selected then C(CYAN,.13); love.graphics.rectangle("fill",20,y-3,W-40,29,4,4); C(CYAN,.7); love.graphics.rectangle("line",20,y-3,W-40,29,4,4) end; T(n.ssid or "Hidden network",29,y+3,W*.42,9,{.91,.95,.98},"left",true); T(tostring(n.signal or 0).."%",W*.58,y+4,50,8,{.54,.76,.88},"right"); icon.draw(n.secure and "lock" or "globe",W-52,y+1,17,{.56,.78,.9}) end
 if #st.networks==0 then T(st.busy and "Scanning…" or "No scan results yet · press A to scan",24,220,W-48,9,{.59,.72,.82},"center") end
 T("Network joining remains managed by muOS; this panel does not store Wi-Fi credentials.",18,H-50,W-36,7,{.66,.76,.84},"center"); T(st.status,12,H-32,W-24,7,{.48,.82,.95},"center"); T("A SCAN   X RADIO ON/OFF   Y REFRESH   B BACK",12,H-15,W-24,8,{.72,.87,.95},"center",true); love.graphics.setColor(1,1,1,1)
end
return M